CREATE TABLE IF NOT EXISTS households (id TEXT PRIMARY KEY,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#4f996c',photo_url TEXT,founder_id TEXT NOT NULL REFERENCES members(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS household_members (household_id TEXT NOT NULL REFERENCES households(id),member_id TEXT NOT NULL UNIQUE REFERENCES members(id),role TEXT NOT NULL CHECK(role IN ('head','member')),joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(household_id,member_id));
CREATE TABLE IF NOT EXISTS household_requests (id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id),requester_id TEXT NOT NULL REFERENCES members(id),recipient_id TEXT NOT NULL REFERENCES members(id),kind TEXT NOT NULL CHECK(kind IN ('join','invite','head')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','cancelled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT);
CREATE INDEX IF NOT EXISTS household_requests_pending ON household_requests(household_id,status);
CREATE TABLE IF NOT EXISTS household_email_invites (id TEXT PRIMARY KEY,household_id TEXT NOT NULL REFERENCES households(id),sender_id TEXT NOT NULL REFERENCES members(id),recipient_email TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,accepted_by TEXT REFERENCES members(id),accepted_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
